import java.util.List;
import java.util.Optional;

public class MemberDirectoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static MemberDirectory directory() {
        return new MemberDirectory(List.of(
                new Member(1, "ana", "ana@mail.com"),
                new Member(2, "bo", "bo@mail.com"),
                new Member(3, "cy", "cy@mail.com")));
    }

    public static void main(String[] args) {
        MemberDirectory dir = directory();
        check("findById hit", Optional.of(new Member(2, "bo", "bo@mail.com")), dir.findById(2));
        check("findById miss", Optional.empty(), dir.findById(99));

        check("findByEmail exact", Optional.of(new Member(1, "ana", "ana@mail.com")),
                dir.findByEmail("ana@mail.com"));
        check("findByEmail ignores case and spaces",
                Optional.of(new Member(1, "ana", "ana@mail.com")), dir.findByEmail("  ANA@Mail.com "));
        check("findByEmail miss", Optional.empty(), dir.findByEmail("nobody@mail.com"));
        check("findByEmail null", Optional.empty(), dir.findByEmail(null));

        check("nameOf hit", "cy", dir.nameOf(3));
        check("nameOf miss", "unknown", dir.nameOf(42));

        MemberDirectory emptyDir = new MemberDirectory(List.of());
        check("empty directory finds nothing", Optional.empty(), emptyDir.findById(1));
        check("empty directory name", "unknown", emptyDir.nameOf(1));
        done();
    }
