import java.util.List;
import java.util.Optional;

/**
 * TASK: Complete MemberDirectory. The Member record above it and the
 * constructor are provided -- do not edit them.
 *
 * A lookup that can miss should say so in its return type, so these finders
 * return Optional instead of null.
 *
 * - findById(id) returns the member with that id, or an empty Optional.
 * - findByEmail(email) matches ignoring capitalisation and surrounding spaces
 *   (" ANA@Mail.com " finds "ana@mail.com"). A null email finds nobody.
 * - nameOf(id) returns that member's name, or "unknown" when there is no such
 *   member. Build it from findById with map and orElse -- no if statement.
 *
 * Example: findById(2) -> Optional[Member[id=2, name=bo, email=bo@mail.com]]
 */
record Member(int id, String name, String email) { }

public class MemberDirectory {

    private final List<Member> members;

    public MemberDirectory(List<Member> members) {
        this.members = members;
    }

    public Optional<Member> findById(int id) {
        for (Member member : members) {
            if (member.id() == id) {
                return Optional.of(member);
            }
        }
        return Optional.empty();
    }

    public Optional<Member> findByEmail(String email) {
        if (email == null) {
            return Optional.empty();
        }
        String wanted = email.trim();
        for (Member member : members) {
            if (member.email().equalsIgnoreCase(wanted)) {
                return Optional.of(member);
            }
        }
        return Optional.empty();
    }

    public String nameOf(int id) {
        return findById(id).map(Member::name).orElse("unknown");
    }
}
